// MNIST inference CLI: ./cli_tool weights.json image.png -> prints predicted digit
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <string>
#include <vector>

#include "lodepng.h"
#include "cJSON.h"

static bool readFile(const char* path, std::string& out) {
    FILE* f = fopen(path, "rb");
    if (!f) return false;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    out.resize((size_t)(n > 0 ? n : 0));
    size_t rd = n > 0 ? fread(&out[0], 1, (size_t)n, f) : 0;
    out.resize(rd);
    fclose(f);
    return true;
}

// Flattens a cJSON array (1-D or 2-D) of numbers into vals.
static bool flatten(const cJSON* arr, std::vector<double>& vals) {
    if (!cJSON_IsArray(arr)) return false;
    const cJSON* it = NULL;
    cJSON_ArrayForEach(it, arr) {
        if (cJSON_IsArray(it)) {
            if (!flatten(it, vals)) return false;
        } else if (cJSON_IsNumber(it)) {
            vals.push_back(it->valuedouble);
        } else {
            return false;
        }
    }
    return true;
}

static const cJSON* findKey(const cJSON* root, const char* const* names, int n) {
    for (int i = 0; i < n; i++) {
        const cJSON* v = cJSON_GetObjectItemCaseSensitive((cJSON*)root, names[i]);
        if (v) return v;
    }
    return NULL;
}

static bool getParam(const cJSON* root, const char* const* names, int n,
                     std::vector<double>& out) {
    const cJSON* v = findKey(root, names, n);
    if (!v) return false;
    out.clear();
    return flatten(v, out);
}

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    std::string js;
    if (!readFile(argv[1], js)) {
        fprintf(stderr, "cannot read %s\n", argv[1]);
        return 1;
    }
    cJSON* root = cJSON_ParseWithLength(js.c_str(), js.size());
    if (!root) {
        fprintf(stderr, "bad json\n");
        return 1;
    }
    // Some checkpoints wrap params under a container key.
    const char* wrapKeys[] = {"state_dict", "model", "weights", "params"};
    const cJSON* obj = root;
    for (int i = 0; i < 4; i++) {
        cJSON* w = cJSON_GetObjectItemCaseSensitive((cJSON*)root, wrapKeys[i]);
        if (w && cJSON_IsObject(w)) { obj = w; break; }
    }

    const char* k_w1[] = {"input_layer.weight", "input_layer_weight", "fc1.weight", "input.weight"};
    const char* k_b1[] = {"input_layer.bias", "input_layer_bias", "fc1.bias", "input.bias"};
    const char* k_w2[] = {"hidden_layer.weight", "hidden_layer_weight", "fc2.weight", "hidden.weight"};
    const char* k_b2[] = {"hidden_layer.bias", "hidden_layer_bias", "fc2.bias", "hidden.bias"};
    const char* k_w3[] = {"output_layer.weight", "output_layer_weight", "fc3.weight", "output.weight"};
    const char* k_b3[] = {"output_layer.bias", "output_layer_bias", "fc3.bias", "output.bias"};

    std::vector<double> W1, B1, W2, B2, W3, B3;
    if (!getParam(obj, k_w1, 4, W1) || !getParam(obj, k_b1, 4, B1) ||
        !getParam(obj, k_w2, 4, W2) || !getParam(obj, k_b2, 4, B2) ||
        !getParam(obj, k_w3, 4, W3) || !getParam(obj, k_b3, 4, B3)) {
        fprintf(stderr, "missing weights\n");
        cJSON_Delete(root);
        return 1;
    }
    cJSON_Delete(root);

    size_t h1 = B1.size(), h2 = B2.size(), nc = B3.size();
    if (h1 == 0 || h2 == 0 || nc == 0 || W1.size() % h1 != 0) {
        fprintf(stderr, "bad shapes\n");
        return 1;
    }
    size_t in = W1.size() / h1;  // 784

    // Decode PNG as grayscale 8-bit.
    std::vector<unsigned char> px;
    unsigned iw = 0, ih = 0;
    unsigned err = lodepng::decode(px, iw, ih, argv[2], LCT_GREY, 8);
    if (err) {
        fprintf(stderr, "png error %u: %s\n", err, lodepng_error_text(err));
        return 1;
    }

    size_t side = (size_t)llround(sqrt((double)in));
    std::vector<double> x(in, 0.0);
    for (size_t r = 0; r < side; r++) {
        for (size_t c = 0; c < side; c++) {
            // Nearest-neighbour sample (identity when the image is already side x side).
            size_t sy = ih == side ? r : (size_t)((r * (size_t)ih) / side);
            size_t sx = iw == side ? c : (size_t)((c * (size_t)iw) / side);
            if (sy >= ih) sy = ih - 1;
            if (sx >= iw) sx = iw - 1;
            double v = px[sy * (size_t)iw + sx] / 255.0;
            x[r * side + c] = (v - 0.1307) / 0.3081;  // MNIST normalisation
        }
    }

    std::vector<double> a(h1), b(h2), o(nc);
    for (size_t i = 0; i < h1; i++) {
        double s = B1[i];
        const double* w = &W1[i * in];
        for (size_t j = 0; j < in; j++) s += w[j] * x[j];
        a[i] = s > 0 ? s : 0;
    }
    for (size_t i = 0; i < h2; i++) {
        double s = B2[i];
        const double* w = &W2[i * h1];
        for (size_t j = 0; j < h1; j++) s += w[j] * a[j];
        b[i] = s > 0 ? s : 0;
    }
    for (size_t i = 0; i < nc; i++) {
        double s = B3[i];
        const double* w = &W3[i * h2];
        for (size_t j = 0; j < h2; j++) s += w[j] * b[j];
        o[i] = s;
    }

    size_t best = 0;
    for (size_t i = 1; i < nc; i++)
        if (o[i] > o[best]) best = i;

    printf("%zu\n", best);
    return 0;
}

